y.sr15-on #sc8Dialog.sr15-review .sr15-groups {\n  grid-column: 1 / -1;\n  grid-row: 6;\n  display: grid;\n  gap: 12px;\n  min-height: 0;\n  /* A second limit, for a browser that does not shrink this row to the dialog's own maximum height: the groups never\n     take more than the screen less the title, the instruction and the action bar, so the bar cannot be pushed out. */\n  max-height: calc(100dvh - 2rem - 13rem);\n  overflow: auto;\n  margin: 0 0 12px;\n  padding: 0 2px 12px;\n  border-bottom: 1px solid var(--line);\n}\nhtml body.sr15-on #sc8Dialog.sr15-review .sr15-groups > fieldset {\n  min-width: 0;\n  margin: 0;\n  padding: 0;\n  border: 0;\n}\nhtml body.sr15-on #sc8Dialog.sr15-review .sr15-groups > fieldset > legend {\n  display: block;\n  box-sizing: border-box;\n  width: 100%;\n  margin: 0 0 4px;\n  padding: 0;\n  font-family: 'EB Garamond', serif;\n  font-size: .9rem;\n  font-weight: 700;\n  line-height: 1.4;\n  color: var(--ink);\n}\nhtml body.sr15-on #sc8Dialog.sr15-review .sr15-count {\n  float: right;\n  padding: 2px 8px;\n  border-radius: 999px;\n  background: rgba(90, 77, 49, .12);\n  color: var(--ink-soft);\n  font-family: 'Noto Sans JP', sans-serif;\n  font-size: .7rem;\n  font-weight: 700;\n  line-height: 1.5;\n  white-space: nowrap;\n}\nhtml body.sr15-on #sc8Dialog.sr15-review .sr15-count[data-state=\"done\"] {\n  background: var(--ink-soft);\n  color: var(--paper);\n}\nhtml body.sr15-on #sc8Dialog.sr15-review .sr15-count[data-state=\"over\"] {\n  background: #a3332a;\n  color: #fff;\n}\nhtml body.sr15-on #sc8Dialog.sr15-review .sr15-groups > fieldset > div + div {\n  margin-top: 4px;\n}\nhtml body.sr15-on #sc8Dialog.sr15-review .oc8-held-spell {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  box-sizing: border-box;\n  min-height: 44px;\n  margin: 0;\n  padding: 4px 8px;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  font-family: 'Noto Sans JP', sans-serif;\n  font-size: .9rem;\n  line-height: 1.35;\n  letter-spacing: no